// Navigation: Home lists the sections and each section opens full width. Opening or leaving a section adds one history entry, so the browser Back and Forward buttons move between Home and sections, and #section links open a section directly.
const SECTION_IDS=['connection','personalization','changelog','notes','docs','support','dimsum','models','status'];
function hashTab(){if(typeof location==='undefined')return null;const raw=String(location.hash||'').replace(/^#/,'');return SECTION_IDS.includes(raw)?raw:'home';}
function recordTab(tab,push){try{if(typeof history==='undefined')return;const url=tab==='home'?location.pathname+location.search:'#'+tab;if(push)history.pushState({tab},'',url);else history.replaceState({tab},'',url);}catch{}}
function renderView(){const home=prefs.tab==='home';$('home-view').hidden=!home;$('home-back').hidden=home;$('workspace-heading').hidden=!home;$('section-title').hidden=home;document.documentElement.dataset.view=home?'home':'section';document.documentElement.dataset.nav=navDirection;$('home-back').setAttribute('aria-label',plainName(['Back to Home','返回主頁']));if(!home)label($('section-title'),copy[prefs.tab]);}
function update(change,{fromHistory=false}={}){const before=prefs;loaded=applyPreferences(storage,prefs,change);prefs=loaded.value;const moved=before.tab!==prefs.tab;if(moved){navDirection=prefs.tab==='home'?'back':'forward';stopSpeech(globalThis.speechSynthesis||null);if(!fromHistory)recordTab(prefs.tab,true);}if(loaded.state==='saved')recordChanges(storage,before,prefs);render();void filterGuidance();if(moved)(prefs.tab==='home'?$('tab-'+before.tab):$('section-title'))?.focus?.();}
