function renderChangelog(){const list=$('changelog-list'),query=String($('changelog-filter').value||'').trim().toLowerCase(),entries=Array.isArray(changelog?.entries)?changelog.entries:[],shown=entries.filter(entry=>!query||changelogText(entry).includes(query));$('changelog-filter').label=t(['Filter changes','篩選更新']);label($('changelog-count'),entries.length?[shown.length+' of '+entries.length+' releases','共 '+entries.length+' 個版本，顯示 '+shown.length+' 個']:['The changelog is unavailable in this build.','呢個組建冇更新記錄。']);list.replaceChildren(...shown.map(entry=>{const card=document.createElement('article'),heading=document.createElement('h3');card.className='changelog-entry';heading.textContent=entry.date?entry.title+' · '+entry.date:entry.title;card.append(heading);if(prefs.language!=='yue'||!entry.yue){const items=document.createElement('ul');for(const text of entry.items){const item=document.createElement('li');item.textContent=text;items.append(item);}card.append(items);}if(entry.yue&&prefs.language!=='en'){const yue=document.createElement('p');yue.lang='zh-HK';yue.textContent=entry.yue;card.append(yue);}return card;}));}
