// Export the filtered changelog: preview, validate, then save locally.
let exportFile=null;
function filteredEntries(){const query=String($('changelog-filter').value||'').trim().toLowerCase(),entries=Array.isArray(changelog?.entries)?changelog.entries:[];return entries.filter(entry=>!query||changelogText(entry).includes(query));}
function openExport(){const format=$('export-format').value||'json',entries=filteredEntries();exportFile=null;try{const text=exportChangelog(entries,format);if(!validateExport(text,format,entries))throw new Error('invalid');exportFile={text,format};$('export-text').textContent=text.length>20000?text.slice(0,20000)+'\n…':text;label($('export-summary'),[entries.length+' releases as '+format.toUpperCase()+'. Release notes only; no settings, pairing data or personal wording are included.',entries.length+' 個版本，格式 '+format.toUpperCase()+'。只包括版本說明，唔包括設定、配對資料或者個人用詞。']);$('export-save').disabled=!entries.length;}catch{$('export-text').textContent='';label($('export-summary'),['The export could not be checked, so it is not offered.','匯出內容核對唔到，所以唔提供下載。']);$('export-save').disabled=true;}void $('export-dialog').show();}
function saveExport(){if(!exportFile)return;const spec=EXPORT_FORMATS[exportFile.format],url=URL.createObjectURL(new Blob([exportFile.text],{type:spec.type})),link=document.createElement('a');link.href=url;link.download='material-file-encryptor-changelog.'+spec.extension;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('export-dialog').close();}
$('export-preview').addEventListener('click',openExport);$('export-save').addEventListener('click',saveExport);$('export-cancel').addEventListener('click',()=>$('export-dialog').close());

// Deliberate confirmation before resetting every browser setting.
function confirmState(){const first=Boolean($('confirm-first').selected),second=Boolean($('confirm-second').selected),slider=$('confirm-slider');slider.disabled=!(first&&second);if(slider.disabled)slider.value=0;const amount=Number(slider.value)||0;$('confirm-execute').disabled=!(first&&second&&amount>=100);label($('confirm-status'),['Confirmation progress: '+amount+'%','確認進度：'+amount+'%']);}
let confirmRun=null;
function confirmAction(title,description,run){confirmRun=run;$('confirm-first').selected=false;$('confirm-second').selected=false;$('confirm-slider').value=0;label($('confirm-title'),title);label($('confirm-action'),description);confirmState();void $('confirm-dialog').show();}
