// Product name: shown in the workspace title, version line and accessible names.
function productName(){return prefs.displayName||'Material File Encryptor';}
// Accent: presets or a typed #rrggbb colour with opacity; contrast is checked before it is applied.
// var, not let: render() runs before this point during start-up.
var accentDraft=null;
function darkTheme(){return prefs.theme==='dark'||(prefs.theme==='system'&&Boolean(globalThis.matchMedia?.('(prefers-color-scheme: dark)')?.matches));}
function draftAccent(){const base=accentDraft??prefs.accent,hex=String(base||'').slice(0,7),alpha=base&&base.length===9?Math.round(parseInt(base.slice(7),16)/255*100):100;return {hex,alpha};}
function composeAccent(hex,alpha){return alpha>=100?hex:hex+Math.round(alpha/100*255).toString(16).padStart(2,'0');}
function renderIdentity(){document.title=productName()+' · '+t(copy.heading);if(prefs.displayName)label($('workspace-heading'),[prefs.displayName+' · '+copy.heading[0],prefs.displayName+' · '+copy.heading[1]]);$('home-view').setAttribute('aria-label',productName()+' · '+t(['Workspace','工作區']));const name=$('display-name');if(!name.matches?.(':focus-within'))name.value=prefs.displayName;name.label=t(['Product name','產品名稱']);name.supportingText=t(['Leave empty to use Material File Encryptor.','留空就用 Material File Encryptor。']);
 const {hex,alpha}=draftAccent(),candidate=hex?composeAccent(hex,alpha):'',palette=candidate?accentPalette(candidate,darkTheme()):null;$('accent-hex').value=hex;$('accent-hex').label=t(['Accent colour','強調色']);$('accent-alpha').value=alpha;$('accent-alpha').setAttribute('aria-label',t(copy.accentAlpha));
 label($('accent-contrast'),!hex?['Default accent in use.','而家用緊預設強調色。']:!palette?['Enter a colour as # followed by six hexadecimal digits.','請輸入 # 加六位十六進制數字嘅顏色。']:palette.passes?['Text contrast '+palette.ratio+':1 meets the 4.5:1 minimum.','文字對比 '+palette.ratio+':1，符合 4.5:1 最低要求。']:['Text contrast '+palette.ratio+':1 is below 4.5:1. Choose a darker or more opaque colour.','文字對比 '+palette.ratio+':1，低過 4.5:1。請揀深色啲或者唔透明啲嘅顏色。']);
 $('accent-apply').disabled=!palette||!palette.passes||candidate===prefs.accent;$('accent-reset').disabled=!prefs.accent&&accentDraft==null;
 applyAccent(document.documentElement,prefs.accent,darkTheme());
 const swatches=$('accent-swatches');swatches.setAttribute('aria-label',t(['Accent presets','強調色預設']));swatches.replaceChildren(...ACCENT_PRESETS.map(preset=>{const button=document.createElement('md-icon-button');button.setAttribute('aria-label',t(['Accent','強調色'])+' '+preset);button.setAttribute('aria-pressed',String(hex===preset));const dot=document.createElement('span');dot.className='swatch';if(dot.style)dot.style.background=preset;button.append(dot);button.addEventListener('click',()=>{accentDraft=composeAccent(preset,draftAccent().alpha);renderIdentity();});return button;}));}
$('display-name').addEventListener('change',()=>{const field=$('display-name'),value=String(field.value||'').trim();if(!validDisplayNameLocal(value)){field.error=true;field.errorText=t(['Use up to 60 characters without angle brackets or line breaks.','最多 60 個字元，唔可以有尖括號或者換行。']);return;}field.error=false;field.errorText='';update({displayName:value});});
