$('accent-hex').addEventListener('input',()=>{const value=String($('accent-hex').value||'').trim().toLowerCase();accentDraft=/^#[0-9a-f]{6}$/.test(value)?composeAccent(value,draftAccent().alpha):value;renderIdentity();});
for(const name of ['input','change'])$('accent-alpha').addEventListener(name,()=>{const {hex}=draftAccent();if(/^#[0-9a-f]{6}$/.test(hex)){accentDraft=composeAccent(hex,Number($('accent-alpha').value)||100);renderIdentity();}});
