// Recent changes: inspect, restore one value, or clear the list after a deliberate confirmation.
function shownValue(field,value){if(field==='emoji')return value?t(['On','開啟']):t(['Off','關閉']);if(field==='displayName')return value||'Material File Encryptor';if(field==='accent')return value||t(['Default','預設']);if(field==='language')return t({en:['English','英文'],yue:['Cantonese','廣東話'],bilingual:['English and Cantonese','英文同廣東話']}[value]||[String(value),String(value)]);if(field==='theme')return t(copy[value]||[String(value),String(value)]);return String(value);}
function fieldNames(field){return {language:['Language','語言'],theme:copy.theme,funnyEnglish:copy.funnyEnglish,funnyCantonese:copy.funnyCantonese,emoji:copy.emoji,displayName:['Product name','產品名稱'],accent:['Accent colour','強調色']}[field];}
function renderHistory(){const entries=readHistory(storage),list=$('history-list');$('history-clear').disabled=!entries.length;list.replaceChildren(...(entries.length?entries.map(entry=>{const row=document.createElement('article');row.className='history-entry';const text=document.createElement('p');text.textContent=t(fieldNames(entry.field))+': '+shownValue(entry.field,entry.from)+' → '+shownValue(entry.field,entry.to)+' · '+entry.at.slice(0,16).replace('T',' ')+' UTC';const restore=document.createElement('md-text-button');restore.textContent=t(['Restore','還原'])+' '+shownValue(entry.field,entry.from);restore.disabled=prefs[entry.field]===entry.from;restore.addEventListener('click',()=>update({[entry.field]:entry.from}));row.append(text,restore);return row;}):[(()=>{const empty=document.createElement('p');label(empty,['No setting changes are recorded in this browser.','呢個瀏覽器未有記錄任何設定改動。']);return empty;})()]));}
$('history-clear').addEventListener('click',()=>confirmAction(['Clear history','清除記錄'],['Clear history: the list of recent setting changes is removed. Current settings stay as they are.','清除記錄：最近設定改動嘅清單會被移除，目前設定保持不變。'],()=>{clearHistory(storage);render();}));

