const logoErrors={'Choose an image file.':['Choose an image file.','請揀一個圖片檔案。'],'Use a PNG, JPEG or WebP image.':['Use a PNG, JPEG or WebP image.','請用 PNG、JPEG 或 WebP 圖片。'],'Use an image of 64 KB or less.':['Use an image of 64 KB or less.','請用 64 KB 或以下嘅圖片。']};
