// Attention modes: local, reversible switches that change presentation only.
function renderAttention(){const modes=readAttention(storage);$('attention-focus').selected=modes.focus;$('attention-reduced').selected=modes.reducedStimulus;$('attention-guided').selected=modes.guided;const root=document.documentElement;root.dataset.focus=String(modes.focus);root.dataset.reducedStimulus=String(modes.reducedStimulus);root.dataset.guided=String(modes.guided);$('attention-reset').disabled=!modes.focus&&!modes.reducedStimulus&&!modes.guided;if(modes.reducedStimulus)$('preview-emoji').hidden=true;}
