const noteErrors={'Enter a title.':['Enter a title.','請輸入標題。'],'Use a title of 80 characters or fewer.':['Use a title of 80 characters or fewer.','標題請用 80 個字元或以下。'],'Write the note before saving.':['Write the note before saving.','儲存之前請先寫筆記。'],'Use 4,000 characters or fewer.':['Use 4,000 characters or fewer.','請用 4,000 個字元或以下。'],'Remove control characters.':['Remove control characters.','請移除控制字元。'],'Delete a note before adding another; 50 is the limit.':['Delete a note before adding another; 50 is the limit.','最多 50 篇，請先刪除一篇。'],'The note could not be saved in this browser.':['The note could not be saved in this browser.','呢個瀏覽器儲存唔到筆記。']};
