$('notes-delete').addEventListener('click',()=>{const ids=[...selectedNotes],count=ids.length;confirmAction(['Delete notes','刪除筆記'],[count===1?'Delete the selected note from this browser.':'Delete '+count+' selected notes from this browser.','由呢個瀏覽器刪除已揀嘅 '+count+' 篇筆記。'],()=>{const results=deleteNotes(storage,ids),done=results.filter(result=>result.outcome==='deleted').length,failed=results.filter(result=>result.outcome==='failed').length,missing=results.filter(result=>result.outcome==='missing').length;selectedNotes=new Set(results.filter(result=>result.outcome==='failed').map(result=>result.id));notesMessage=['Deleted '+done+' of '+count+'.'+(failed?' '+failed+' could not be deleted and stay selected.':'')+(missing?' '+missing+' were already gone.':''),'已刪除 '+count+' 篇之中嘅 '+done+' 篇。'+(failed?failed+' 篇刪除唔到，仍然揀咗。':'')+(missing?missing+' 篇早已唔喺度。':'')];renderNotes();renderNoteReader();});});
