$('note-new').addEventListener('click',()=>openSheet($('note-new')));
$('note-next').addEventListener('click',()=>{if(!sheet)return;const problem=stepError(sheet.step);if(problem){sheet.error=noteErrors[problem]||[problem,problem];renderSheet();return;}if(sheet.step<3){sheet.step+=1;sheet.error=null;saveDraft(storage,sheetDraft());renderSheet();return;}const result=addNote(storage,sheetDraft());if(result.error){sheet.error=noteErrors[result.error]||[result.error,result.error];renderSheet();return;}clearDraft(storage);notesMessage=['Saved “'+result.note.title+'”.','已儲存「'+result.note.title+'」。'];closeSheet();renderNotes();});
$('note-back').addEventListener('click',()=>{if(!sheet||sheet.step===1)return;sheet.step-=1;sheet.error=null;saveDraft(storage,sheetDraft());renderSheet();});
