// Scheduled changes: dated theme or language changes in this computer's time zone; missed ones run when the workspace next opens.
var scheduleMessage;
// Functions, not constants: render() reaches these during start-up, before this point runs.
function scheduleName(field){return {theme:copy.theme,language:['Language','語言']}[field];}
function valueName(value){return {system:copy.system,light:copy.light,dark:copy.dark,en:['English','英文'],yue:['Cantonese','廣東話'],bilingual:['English and Cantonese','英文同廣東話']}[value];}
