function renderSchedules(){const field=$('schedule-field').value||'theme',select=$('schedule-value'),current=select.value;label($('schedule-zone'),['Times use this computer\'s time zone: '+timeZoneLabel()+'.','時間跟呢部電腦嘅時區：'+timeZoneLabel()+'。']);$('schedule-field').label=t(['Setting','設定']);select.label=t(['Value','數值']);$('schedule-at').label=t(['When','時間']);select.replaceChildren(...SCHEDULE_VALUES[field].map(value=>{const option=document.createElement('md-select-option');option.value=value;const headline=document.createElement('div');headline.slot='headline';headline.textContent=t(valueName(value));option.append(headline);if(value===current||(!SCHEDULE_VALUES[field].includes(current)&&value===SCHEDULE_VALUES[field][0]))option.selected=true;return option;}));if(!SCHEDULE_VALUES[field].includes(current))select.value=SCHEDULE_VALUES[field][0];const list=readSchedules(storage);$('schedule-list').replaceChildren(...list.map(item=>{const row=document.createElement('article');row.className='history-entry';const text=document.createElement('p');text.textContent=t(scheduleName(item.field))+' → '+t(valueName(item.value))+' · '+localTime(item.at);const cancel=document.createElement('md-text-button');cancel.textContent=t(['Cancel','取消']);cancel.addEventListener('click',()=>{scheduleMessage=cancelSchedule(storage,item.id)?['Scheduled change cancelled.','已取消預定改動。']:['That change was already gone.','嗰個改動早已唔喺度。'];renderSchedules();});row.append(text,cancel);return row;}));label($('schedule-status'),scheduleMessage||(list.length?[list.length===1?'1 change scheduled.':list.length+' changes scheduled.','已預定 '+list.length+' 個改動。']:['No changes are scheduled.','未有預定改動。']));}
const scheduleErrors={'Choose a setting and a value.':['Choose a setting and a value.','請揀設定同數值。'],'Choose a date and time.':['Choose a date and time.','請揀日期同時間。'],'Choose a time at least one minute from now.':['Choose a time at least one minute from now.','請揀最少一分鐘之後嘅時間。'],'Cancel a scheduled change first; 20 is the limit.':['Cancel a scheduled change first; 20 is the limit.','最多 20 個，請先取消一個。'],'Another change to this setting is already scheduled for that minute.':['Another change to this setting is already scheduled for that minute.','同一分鐘已經預定咗呢個設定嘅另一個改動。'],'The schedule could not be saved in this browser.':['The schedule could not be saved in this browser.','呢個瀏覽器儲存唔到預定。']};
$('schedule-field').addEventListener('change',()=>renderSchedules());
$('schedule-add').addEventListener('click',()=>{const local=String($('schedule-at').value||''),when=local?new Date(local):null,result=addSchedule(storage,{field:$('schedule-field').value||'theme',value:$('schedule-value').value,at:when&&!Number.isNaN(when.getTime())?when.toISOString():''});scheduleMessage=result.error?scheduleErrors[result.error]||[result.error,result.error]:['Scheduled for '+localTime(result.schedule.at)+'.','已預定喺 '+localTime(result.schedule.at)+'。'];renderSchedules();});
function runDueSchedules(){const due=takeDue(storage);if(!due.length)return;for(const item of due)update({[item.field]:item.value});const overdue=due.filter(item=>item.overdue);scheduleMessage=overdue.length?['Applied '+due.length+' scheduled changes, including '+overdue.length+' missed while this workspace was closed (earliest due '+localTime(overdue[0].at)+').','已套用 '+due.length+' 個預定改動，其中 '+overdue.length+' 個係工作區關閉期間錯過咗（最早應該喺 '+localTime(overdue[0].at)+'）。']:['Applied '+due.length+' scheduled changes.','已套用 '+due.length+' 個預定改動。'];renderSchedules();}
runDueSchedules();if(typeof setInterval==='function')setInterval(runDueSchedules,30000);

// Offline documentation: the full bundled catalogue, searchable, with internal links routed inside the workspace.
