$('narration-voice').addEventListener('change',()=>{saveNarration(storage,{...readNarration(storage),voice:$('narration-voice').value});renderNarration();});
for(const name of ['change','input'])$('narration-rate').addEventListener(name,()=>{saveNarration(storage,{...readNarration(storage),rate:Number($('narration-rate').value)||1});});
$('narration-read').addEventListener('click',readCurrentTab);$('narration-stop').addEventListener('click',stopReading);
