const ticketErrors={'Enter a title.':['Enter a title.','請輸入標題。'],'Describe what happened.':['Describe what happened.','請描述發生咗乜事。'],'Choose a category.':['Choose a category.','請揀類別。'],'Attach at most 3 files.':['Attach at most 3 files.','最多附加 3 個檔案。'],'Attach PNG, JPEG, WebP, text or JSON files.':['Attach PNG, JPEG, WebP, text or JSON files.','只可以附加 PNG、JPEG、WebP、文字或者 JSON 檔案。'],'Attach files of 200 KB or less.':['Attach files of 200 KB or less.','附加檔案要 200 KB 或以下。']};
