// Screen recording: the browser's own picker chooses the surface; saving needs an explicit privacy review.
var recorder,recordingStream,recordingChunks,recordingUrl,recordingMessage;
function renderRecording(){const active=recorder?.state==='recording',ready=Boolean(recordingUrl);$('recording-start').disabled=active||ready;$('recording-stop').disabled=!active;$('recording-preview').hidden=!ready;$('recording-reviewed').disabled=!ready;if(!ready)$('recording-reviewed').checked=false;$('recording-save').disabled=!ready||!$('recording-reviewed').checked;$('recording-discard').disabled=!ready;label($('recording-status'),recordingMessage||(active?['Recording. Choose Stop recording or stop sharing in the browser to finish.','錄緊。撳「停止錄影」或者喺瀏覽器停止分享就會完成。']:ready?['Watch the recording, confirm it shows nothing private, then save it.','睇一次錄影，確認冇私人資料，然後先儲存。']:['No recording.','未有錄影。']));}
function finishRecording(){if(recorder?.state==='recording')recorder.stop();for(const track of recordingStream?.getTracks?.()||[])track.stop();}
$('recording-start').addEventListener('click',async()=>{const devices=globalThis.navigator?.mediaDevices;if(!devices?.getDisplayMedia||typeof MediaRecorder!=='function'){recordingMessage=['Screen recording is not available in this browser.','呢個瀏覽器唔支援螢幕錄影。'];renderRecording();return;}try{recordingStream=await devices.getDisplayMedia({video:true,audio:false});}catch{recordingMessage=['Recording did not start because no tab or window was chosen.','冇揀分頁或者視窗，所以冇開始錄影。'];renderRecording();return;}recordingChunks=[];recorder=new MediaRecorder(recordingStream);recorder.ondataavailable=event=>{if(event.data?.size)recordingChunks.push(event.data);};recorder.onstop=()=>{recordingUrl=URL.createObjectURL(new Blob(recordingChunks,{type:'video/webm'}));$('recording-preview').src=recordingUrl;recordingMessage=null;renderRecording();};for(const track of recordingStream.getTracks?.()||[])track.addEventListener?.('ended',finishRecording);recorder.start();recordingMessage=null;renderRecording();});
$('recording-stop').addEventListener('click',finishRecording);
$('recording-reviewed').addEventListener('change',renderRecording);
$('recording-save').addEventListener('click',()=>{if(!recordingUrl||!$('recording-reviewed').checked)return;const link=document.createElement('a');link.href=recordingUrl;link.download='screen-recording.webm';link.click();recordingMessage=['Recording saved to this computer.','錄影已經儲存喺呢部電腦。'];renderRecording();});
$('recording-discard').addEventListener('click',()=>{if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingUrl=null;recorder=null;recordingMessage=['Recording discarded.','已捨棄錄影。'];renderRecording();});

// Links in notes: https links open in a new tab without a referrer or opener; anything else stays plain text and says why.
function noteBodyParts(text){return linkParts(text).map(part=>{if(part.text!==undefined)return document.createTextNode(part.text);if(part.safe){const link=document.createElement('a');link.href=part.link;link.target='_blank';link.rel='noopener noreferrer';link.referrerPolicy='no-referrer';link.textContent=part.link;return link;}const blocked=document.createElement('span');blocked.className='link-unavailable';blocked.textContent=part.link+' '+t(['(only secure https links open)','（只會打開安全嘅 https 連結）']);return blocked;});}

// Dim sum catalogue: loaded from GitHub only on request, cached for a day, searched locally; illustrations load one at a time.
var dimsumCatalog,dimsumPhotos,dimsumMessage,dimsumSelected,dimsumLimit,dimsumMineOnly;
const DAY=86400000;
async function cachedJson(url,force){const cache=await globalThis.caches?.open?.('mfe-dimsum-v1').catch(()=>null);if(cache&&!force){const hit=await cache.match(url);const fetchedAt=Date.parse(hit?.headers?.get?.('x-mfe-fetched-at')||'');if(hit&&Date.now()-fetchedAt<DAY)return {json:await hit.json(),fetchedAt:new Date(fetchedAt).toISOString(),cached:true};}const response=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const body=await response.text();const now=new Date().toISOString();if(cache)await cache.put(url,new Response(body,{headers:{'content-type':'application/json','x-mfe-fetched-at':now}})).catch(()=>{});return {json:JSON.parse(body),fetchedAt:now,cached:false};}
async function loadDimsum(force=false){dimsumMessage=['Loading the catalogue from GitHub…','由 GitHub 載入緊目錄…'];$('dimsum-load').disabled=true;renderDimsum();try{const catalog=await cachedJson(CATALOG_URL,force),normalised=normaliseCatalog(catalog.json);if(!normalised||!normalised.dishes.length)throw new Error('empty');let photos=new Map(),photoNote=null;try{photos=photoMap((await cachedJson(RELEASES_URL,force)).json);}catch{photoNote=['Illustrations are unavailable right now; dish details still work.','插圖暫時用唔到，菜式資料照樣可以睇。'];}dimsumCatalog=normalised;dimsumPhotos=photos;dimsumLimit=50;dimsumMessage=photoNote||[normalised.total+' dishes loaded'+(catalog.cached?' from the copy kept on '+catalog.fetchedAt.slice(0,16).replace('T',' ')+' UTC.':' from GitHub.'),'已載入 '+normalised.total+' 款菜式'+(catalog.cached?'（用 '+catalog.fetchedAt.slice(0,16).replace('T',' ')+' UTC 保存嘅副本）。':'（由 GitHub 載入）。')];}catch{dimsumMessage=['The catalogue could not be loaded. Check the connection and try again; nothing else in the workspace needs the network.','載入唔到目錄。請檢查網絡再試；工作區其他功能都唔使網絡。'];}$('dimsum-load').disabled=false;renderDimsum();}
function dishName(dish){return prefs.language==='yue'?(dish.name.zhHant||dish.name.en):prefs.language==='bilingual'&&dish.name.zhHant?dish.name.en+' · '+dish.name.zhHant:dish.name.en;}
function renderDimsum(){const loaded=Boolean(dimsumCatalog);$('dimsum-browser').hidden=!loaded;$('dimsum-refresh').disabled=!loaded;label($('dimsum-status'),dimsumMessage||['The catalogue has not been loaded in this session.','今次未載入目錄。']);if(!loaded)return;const favourites=readFavourites(storage),select=$('dimsum-category'),current=select.value||'';$('dimsum-search').label=t(['Search dishes','搜尋菜式']);select.label=t(['Category','類別']);select.replaceChildren(...['',...categories(dimsumCatalog.dishes)].map(value=>{const option=document.createElement('md-select-option');option.value=value;const headline=document.createElement('div');headline.slot='headline';headline.textContent=value?value.replace(/-/g,' '):t(['All categories','所有類別']);option.append(headline);if(value===current)option.selected=true;return option;}));$('dimsum-mine').setAttribute('aria-pressed',String(Boolean(dimsumMineOnly)));label($('dimsum-mine'),dimsumMineOnly?['Show all dishes','顯示所有菜式']:['Show my list','顯示我嘅清單']);const found=searchDishes(dimsumCatalog.dishes,{query:$('dimsum-search').value||'',category:current,only:dimsumMineOnly?favourites:null}),limit=dimsumLimit||50,shown=found.slice(0,limit);label($('dimsum-count'),[found.length+' of '+dimsumCatalog.total+' dishes','共 '+dimsumCatalog.total+' 款，搵到 '+found.length+' 款']);$('dimsum-more').hidden=found.length<=limit;$('dimsum-list').replaceChildren(...shown.map(dish=>{const item=document.createElement('md-list-item');item.type='button';item.textContent=dishName(dish)+(favourites.has(dish.id)?' ★':'');if(dish.id===dimsumSelected)item.setAttribute('data-current','');item.addEventListener('click',()=>{dimsumSelected=dish.id;renderDimsum();$('dimsum-detail').focus?.();});return item;}));renderDish(favourites);}
function renderDish(favourites){const host=$('dimsum-detail'),dish=dimsumCatalog?.dishes.find(item=>item.id===dimsumSelected);host.replaceChildren();if(!dish){const hint=document.createElement('p');label(hint,['Choose a dish to see its description and illustration.','揀一款菜式睇描述同插圖。']);host.append(hint);return;}const heading=document.createElement('h1');heading.textContent=dishName(dish);const meta=document.createElement('p');meta.textContent=[dish.jyutping,dish.category.replace(/-/g,' '),dish.subcategory].filter(Boolean).join(' · ');const description=document.createElement('p');description.textContent=prefs.language==='yue'?(dish.description.yue||dish.description.en):prefs.language==='bilingual'?[dish.description.en,dish.description.yue].filter(Boolean).join(' '):dish.description.en;host.append(heading,meta,description);for(const [pair,values] of [[['Ingredients','材料'],dish.ingredients],[['Allergens','致敏原'],dish.allergens],[['Dietary notes','飲食備註'],dish.dietaryTags]]){if(!values.length)continue;const line=document.createElement('p');line.textContent=t(pair)+': '+values.join(', ');host.append(line);}const photo=dish.imageFile?dimsumPhotos?.get(dish.imageFile):null;if(photo){const figure=document.createElement('figure');figure.className='dimsum-figure';const image=document.createElement('img');image.src=photo.url;image.alt=prefs.language==='yue'?(dish.alt.yue||dish.alt.en):dish.alt.en||dishName(dish);image.referrerPolicy='no-referrer';image.loading='lazy';image.decoding='async';const caption=document.createElement('figcaption');label(caption,['Generated illustration from the public dim sum catalogue ('+photo.release+'), not a photograph of a real dish.','公開點心目錄嘅生成插圖（'+photo.release+'），唔係真實菜式相片。']);image.addEventListener('error',()=>{figure.replaceChildren();const missing=document.createElement('p');label(missing,['The illustration could not be loaded.','插圖載入唔到。']);figure.append(missing);});figure.append(image,caption);host.append(figure);}else{const missing=document.createElement('p');missing.className='dimsum-missing';label(missing,['No illustration has been published for this dish yet.','呢款菜式暫時未有插圖。']);host.append(missing);}const toggle=document.createElement('md-outlined-button');label(toggle,favourites.has(dish.id)?['Remove from my list','由我嘅清單移除']:['Add to my list','加入我嘅清單']);toggle.addEventListener('click',()=>{const result=toggleFavourite(storage,dish.id);if(result.error)dimsumMessage=[result.error,result.error];renderDimsum();});host.append(toggle);}
$('dimsum-load').addEventListener('click',()=>void loadDimsum(false));$('dimsum-refresh').addEventListener('click',()=>void loadDimsum(true));
$('dimsum-search').addEventListener('input',()=>{dimsumLimit=50;renderDimsum();});$('dimsum-category').addEventListener('change',()=>{dimsumLimit=50;renderDimsum();});
$('dimsum-mine').addEventListener('click',()=>{dimsumMineOnly=!dimsumMineOnly;dimsumLimit=50;renderDimsum();});$('dimsum-more').addEventListener('click',()=>{dimsumLimit=(dimsumLimit||50)+50;renderDimsum();});

// Release code name: fetched from the public release list only when the button is chosen; text nodes and one image element, never markup strings.
// var, not let or const: render() runs before this point during start-up.
var releaseState=null;
var RELEASE_TIMEOUT=10000;
function releaseDetail(release,heading){
 const body=String(release.body||''),name=parseReleaseCodeName(body),photo=parsePhotoUrl(body),page=releasePageUrl(release);
 $('release-result').hidden=false;label($('release-tag'),[heading[0]+release.tag_name,heading[1]+release.tag_name]);
 label($('release-name'),name?['Code name: '+name.english+' / '+name.chinese,'代號：'+name.english+' / '+name.chinese]:['This release lists no code name.','呢個發行版本冇列出代號。']);
 const figure=$('release-figure');figure.replaceChildren();figure.hidden=!photo;
 if(photo){const image=document.createElement('img');image.src=photo;image.alt=name?(prefs.language==='yue'?name.chinese:name.english):'';image.referrerPolicy='no-referrer';image.loading='lazy';image.decoding='async';const caption=document.createElement('figcaption');label(caption,['Dish photo linked from the release notes; it is not a photograph of this build.','菜式相片連結自發行說明，並非呢個組建嘅相片。']);image.addEventListener('error',()=>{figure.replaceChildren();const missing=document.createElement('p');label(missing,['The photo could not be loaded.','相片載入唔到。']);figure.append(missing);});figure.append(image,caption);}
 const link=$('release-link');link.hidden=!page;if(page){link.href=page;label(link,['Open the release on GitHub','喺 GitHub 打開發行頁面']);}
 const installer=installerAsset(release),download=$('release-installer');download.hidden=!installer;if(installer){const megabytes=(installer.size/1048576).toFixed(1);download.href=installer.url;label(download,['Download the desktop installer for '+release.tag_name+' ('+megabytes+' MB). It also carries these extension files.','下載 '+release.tag_name+' 嘅桌面安裝程式（'+megabytes+' MB），入面亦都有呢套擴充功能檔案。']);}
}
function renderRelease(){
 const check=$('release-check');if(!check)return;const state=releaseState;
 check.disabled=state?.phase==='loading';
 label($('release-status'),!state?['Releases have not been checked in this session.','今次未檢查發行版本。']:state.message||['','']);
 if(!state||!state.result){$('release-result').hidden=true;return;}
 const outcome=state.result;
 if(outcome.state==='matched')releaseDetail(outcome.release,['Release ','發行版本 ']);
 else if(outcome.latest)releaseDetail(outcome.latest,['Latest published (not this build): ','最新已發佈（唔係呢個組建）：']);
 else $('release-result').hidden=true;
}
async function checkReleases(){
 if(releaseState?.phase==='loading')return;
 releaseState={phase:'loading',message:['Checking GitHub releases…','檢查緊 GitHub 發行版本…'],result:null};renderRelease();
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),RELEASE_TIMEOUT);
 try{
  const response=await fetch(RELEASES_API,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',redirect:'error',signal:controller.signal});
  if(response.status===403||response.status===429){releaseState={phase:'error',message:['GitHub is limiting requests right now. Try again in a while.','GitHub 暫時限制咗請求，請稍後再試。'],result:null};return;}
  if(!response.ok)throw new Error('HTTP '+response.status);
  const text=await response.text();if(text.length>2000000)throw new Error('too large');
  const releases=JSON.parse(text);if(!Array.isArray(releases))throw new Error('unexpected');
  const version=provenance?.version||chrome.runtime.getManifest().version,commit=provenance&&provenance.sourceModified===false?provenance.sourceCommit:null,result=matchRelease(releases,version,commit);
  releaseState={phase:'done',result,message:result.state==='matched'?['The published release for this build was found.','搵到呢個組建對應嘅已發佈版本。']:result.latest?['No published release matches this build (version '+version+'). The newest published release is shown instead and is not this build.','冇已發佈版本對應呢個組建（版本 '+version+'）。改為顯示最新已發佈版本，佢唔係呢個組建。']:['No published release was found, and none matches this build (version '+version+').','搵唔到任何已發佈版本，亦冇版本對應呢個組建（版本 '+version+'）。']};
 }catch{
  releaseState={phase:'error',message:['Releases could not be checked. Check the connection and try again; nothing else in the workspace needs the network.','檢查唔到發行版本。請檢查網絡再試；工作區其他功能都唔使網絡。'],result:null};
 }finally{clearTimeout(timer);renderRelease();}
}
$('release-check').addEventListener('click',()=>void checkReleases());

// Feature coverage: the bundled inventory record, filtered locally. A status is a record, never proof of delivery.
var coverageStatus='';
var coverageKey='';
function coverageStatusCopy(){return {implemented:['Implemented (recorded)','已記錄為實作'],unverified:['Unverified','未驗證'],missing:['Missing','欠缺'],'not-applicable':['Not applicable','不適用']};}
function coverageRows(){return Array.isArray(coverage?.rows)?coverage.rows:[];}
function statusName(status){return t(coverageStatusCopy()[status]||[status,status]);}
function renderCoverage(){
 const select=$('coverage-status');if(!select)return;const rows=coverageRows(),counts=coverage?.counts||{},statuses=Object.keys(counts).sort();
 $('coverage-search').label=t(['Search coverage','搜尋涵蓋']);select.label=t(['Status','狀態']);$('coverage-list').setAttribute('aria-label',t(['Feature coverage','功能涵蓋']));
 const commit=typeof coverage?.sourceCommit==='string'?coverage.sourceCommit.slice(0,12):'';
 label($('coverage-counts'),rows.length?[rows.length+' records'+(commit?' from commit '+commit:'')+': '+statuses.map(status=>counts[status]+' '+(coverageStatusCopy()[status]||[status])[0].toLowerCase()).join(', ')+'.',rows.length+' 項紀錄'+(commit?'（提交 '+commit+'）':'')+'：'+statuses.map(status=>counts[status]+' '+(coverageStatusCopy()[status]||[status,status])[1]).join('、')+'。']:['The coverage record is unavailable in this build.','呢個組建冇涵蓋紀錄。']);
 const key=prefs.language+'|'+statuses.map(status=>status+counts[status]).join(',');
 if(key!==coverageKey){coverageKey=key;const options=['',...statuses].map(value=>{const option=document.createElement('md-select-option');option.value=value;const headline=document.createElement('div');headline.slot='headline';headline.textContent=value?statusName(value)+' ('+counts[value]+')':t(['All statuses','所有狀態'])+' ('+rows.length+')';option.append(headline);return option;});select.replaceChildren(...options);select.value=coverageStatus||'';
  /* Select after the options are connected so the field shows the chosen status. */
  void Promise.resolve(select.updateComplete).then(()=>{const index=Array.from(select.children||[]).findIndex(item=>item.value===(coverageStatus||''));if(index>=0&&typeof select.selectIndex==='function')select.selectIndex(index);});}
 renderCoverageList();
}
function renderCoverageList(){
 const rows=coverageRows(),query=String($('coverage-search').value||'').trim().toLowerCase(),shown=rows.filter(row=>(!coverageStatus||row.status===coverageStatus)&&(!query||(row.id+' '+row.status+' '+row.reason).toLowerCase().includes(query)));
 label($('coverage-shown'),rows.length?['Showing '+shown.length+' of '+rows.length+' records.','顯示 '+rows.length+' 項之中嘅 '+shown.length+' 項。']:['','']);
 $('coverage-list').replaceChildren(...shown.map(row=>{const item=document.createElement('md-list-item'),headline=document.createElement('div'),detail=document.createElement('div'),chip=document.createElement('span');item.className='coverage-row';headline.slot='headline';headline.textContent=row.id;detail.slot='supporting-text';detail.lang='en';detail.textContent=row.reason;chip.slot='end';chip.className='status-chip';chip.dataset.status=row.status;chip.textContent=statusName(row.status);item.append(headline,detail,chip);return item;}));
}
$('coverage-search').addEventListener('input',()=>renderCoverageList());
$('coverage-status').addEventListener('change',()=>{coverageStatus=String($('coverage-status').value||'');renderCoverageList();});

// Full notes use the same Markdown renderer as bundled documentation.
var openedNoteId;
function noteReaderTranslation(value){const pairs={'Image unavailable':['Image unavailable','圖片未可用'],'Linked content is not bundled.':['Relative links are unavailable in local notes.','本機筆記唔提供相對連結。'],'Only HTTPS links without credentials can open.':['Only HTTPS links without credentials can open.','只可以打開冇登入資料嘅 HTTPS 連結。'],'No text was provided.':['No text was provided.','未有提供文字。'],'Opens an external website':['Opens an external website','打開外部網站'],'Documentation table':['Note table','筆記表格'],'Details':['Details','詳情']};return pairs[value]?t(pairs[value]):value;}
function renderNoteReader(){const note=readNotes(storage).find(item=>item.id===openedNoteId),reader=$('note-reader');reader.hidden=!note;if(!note){openedNoteId=null;$('note-reader-title').textContent='';$('note-reader-body').replaceChildren();return;}$('note-reader-title').textContent=note.title;renderNoteText($('note-reader-body'),note.body,renderMarkdown,noteReaderTranslation);label($('note-reader-close'),['Close note','關閉筆記']);label($('note-reader-export'),['Export full note','匯出完整筆記']);}
$('note-reader-close').addEventListener('click',()=>{openedNoteId=null;renderNoteReader();$('note-new').focus?.();});
$('note-reader-export').addEventListener('click',()=>{const note=readNotes(storage).find(item=>item.id===openedNoteId);if(!note){renderNoteReader();return;}const url=URL.createObjectURL(new Blob([notesMarkdown([note])],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='note.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

// Local models: one loopback model server. The host permission is requested on the Connect click, requests go only to
// 127.0.0.1, and the conversation lives in memory for this page only.
var models;
function mstate(){return models??={port:DEFAULT_PORT,server:null,checked:false,installed:[],running:new Set(),message:null,pull:null,pullMessage:null,chat:[],chatAbort:null,chatTail:null,chatMessage:null,deleting:null,copyMessage:null,generation:0};}
var modelErrorCopy={'Use a port from 1024 to 65535.':['Use a port from 1024 to 65535.','請用 1024 至 65535 之間嘅埠。'],'Select a valid local model tag. Cloud models are not supported.':['Select a valid local model tag. Cloud models are not supported.','請輸入有效嘅本機模型標籤，唔支援雲端模型。'],'The request was cancelled.':['The request was cancelled.','已取消要求。'],'The local model server did not answer in time.':['The local model server did not answer in time.','本機模型伺服器喺限時內冇回應。'],'The model stream ended before it finished.':['The model stream ended before it finished.','模型串流未完成就結束咗。'],'Select a model first.':['Select a model first.','請先揀模型。']};
function modelError(error){const text=String(error?.message||''),known=modelErrorCopy[text];if(known)return known;if(error?.kind==='unreachable')return [text,'本機模型伺服器冇運行，或者連唔到埠 '+(/port (\d+)/.exec(text)?.[1]||'')+'。'];if(error?.kind==='http')return [text,'本機模型伺服器回覆 HTTP '+(/HTTP (\d+)/.exec(text)?.[1]||'')+'。'];return [text||'The request did not complete.',error?.kind==='server'?'本機模型伺服器未能完成呢個操作，請檢查模型同伺服器狀態。':error?.kind==='protocol'?'本機模型伺服器傳咗意外嘅資料。':'要求未完成。'];}
function modelCall(action,body,extra={}){return callLocal(action,body,{port:mstate().port,fetchImpl:(...args)=>fetch(...args),...extra});}
function appendAll(node,children){for(const child of children)node.append(child);return node;}
// Rich text: tokens become elements with createElement and textContent only; links open in a new tab without opener or referrer.
function richInline(tokens){return tokens.map(token=>{if(token.type==='text')return document.createTextNode(token.text);const node=document.createElement({code:'code',bold:'strong',italic:'em',link:'a'}[token.type]);if(token.type==='link'){node.href=token.href;node.target='_blank';node.rel='noopener noreferrer';node.referrerPolicy='no-referrer';node.textContent=token.text;}else if(token.type==='code')node.textContent=token.text;else appendAll(node,richInline(token.children));return node;});}
