function chatEntry(message,last){const m=mstate(),entry=document.createElement('article'),role=document.createElement('p');entry.className='chat-message';entry.dataset.role=message.role;role.className='chat-role';label(role,message.role==='user'?['You','你']:['Model','模型']);entry.append(role);if(message.role==='user'){const body=document.createElement('p');body.className='chat-user-text';body.textContent=message.content;entry.append(body);return entry;}const body=document.createElement('div'),actions=document.createElement('div'),copyReply=document.createElement('md-text-button');body.className='chat-rich';renderRich(body,message.content);actions.className='chat-actions';label(copyReply,['Copy response','複製回覆']);copyReply.addEventListener('click',()=>void copyText(message.content));actions.append(copyReply);entry.append(body);entry.append(actions);if(last)m.chatTail={body,message};return entry;}
