function renderPullProgress(){const m=mstate(),bar=$('models-pull-progress');bar.hidden=!m.pull;if(m.pull){bar.indeterminate=m.pull.fraction===null;bar.value=m.pull.fraction??0;}label($('models-pull-status'),m.pull?['Pulling “'+m.pull.name+'”'+(m.pull.status?': '+m.pull.status:'')+(m.pull.fraction===null?'':' ('+Math.round(m.pull.fraction*100)+'%)')+'.','拉取緊「'+m.pull.name+'」'+(m.pull.status?'：'+m.pull.status:'')+(m.pull.fraction===null?'':'（'+Math.round(m.pull.fraction*100)+'%）')+'。']:m.pullMessage||['Enter a model tag such as llama3.2:3b. Cloud models are not supported.','輸入模型標籤，例如 llama3.2:3b。唔支援雲端模型。']);}
