 $('models-list').replaceChildren(...(m.installed.length?m.installed.map(model=>{const running=m.running.has(model.name),row=document.createElement('article'),text=document.createElement('p'),name=document.createElement('span'),remove=document.createElement('md-text-button');row.className='history-entry model-row';row.dataset.running=String(running);name.className='model-name';name.textContent=model.name;text.append(name);text.append(document.createTextNode(' · '+formatSize(model.size)+(running?' · '+t(['running','運行中']):'')));remove.textContent=t(['Delete','刪除']);remove.setAttribute('aria-label',t(['Delete','刪除'])+' '+model.name);remove.disabled=pulling;remove.addEventListener('click',()=>{m.deleting=model.name;label($('models-delete-text'),['Delete the model “'+model.name+'” from this computer? It has to be pulled again to use it.','由呢部電腦刪除模型「'+model.name+'」？日後要用就要重新拉取。']);void $('models-delete-dialog').show();});row.append(text);row.append(remove);return row;}):[(()=>{const empty=document.createElement('p');label(empty,m.server?['No models are installed. Pull one below.','未安裝任何模型，請喺下面拉取一個。']:['Connect to see the installed models.','連線之後先會顯示已安裝模型。']);return empty;})()]));
 renderPullProgress();
