async function sendChat(){
 const m=mstate();if(!m.server||m.chatAbort)return;const model=$('chat-model').value,prompt=String($('chat-prompt').value||'');
 if(!model){m.chatMessage=['Choose a model first.','請先揀模型。'];renderModels();return;}
 if(!prompt.trim()){m.chatMessage=['Write a message first.','請先寫訊息。'];renderModels();return;}
 if(m.chat.length+2>LIMITS.messages){m.chatMessage=['The conversation is too long. Clear it to continue.','對話太長，請清除後再繼續。'];renderModels();return;}
 const history=[...m.chat.map(({role,content})=>({role,content})),{role:'user',content:prompt}];
 try{validatePayload('chat',{model,messages:history});}catch(error){m.chatMessage=modelError(error);renderModels();return;}
 const reply={role:'assistant',content:''},abort=new AbortController();let capped=false;m.chat.push({role:'user',content:prompt},reply);m.chatAbort=abort;m.chatMessage=null;$('chat-prompt').value='';renderModels();
 try{await modelCall('chat',{model,messages:history},{signal:abort.signal,timeout:600000,onChunk:chunk=>{reply.content+=chatDelta(chunk);if(reply.content.length>LIMITS.prompt){reply.content=reply.content.slice(0,LIMITS.prompt);capped=true;abort.abort();}updateTail();}});}
 catch(error){if(capped)m.chatMessage=['The reply reached the 65,536 character limit and was stopped.','回覆去到 65,536 個字元上限，已經停止。'];else if(error?.kind==='cancelled')m.chatMessage=['Stopped. The partial reply is kept.','已停止，部分回覆會保留。'];else m.chatMessage=modelError(error);if(!reply.content){m.chat.splice(m.chat.indexOf(reply)-1,2);$('chat-prompt').value=prompt;}}
 m.chatAbort=null;renderModels();}
