function renderEditorWorkflow(){label($('editor-heading'),['External editor','外部編輯器']);label($('editor-help'),['Choose a file and a signed supported editor in the desktop pickers, then confirm launch there. File paths and content stay on the desktop. A request expires after two minutes.','喺桌面選擇器揀檔案同已簽署嘅支援編輯器，再喺桌面確認開啟。檔案路徑同內容只留喺桌面。要求兩分鐘後會到期。']);label($('editor-open'),['Choose file and editor on desktop','喺桌面揀檔案同編輯器']);label($('editor-cancel'),['Cancel request and disconnect','取消要求同中斷連線']);$('editor-open').disabled=!editorAvailable||busy||editorPending;$('editor-cancel').hidden=!editorPending;label($('editor-state'),editorPending?['Waiting for desktop selection and confirmation.','等待桌面揀選同確認。']:editorOutcome|| (editorAvailable?['Ready. Every launch needs desktop confirmation.','準備好，每次開啟都要桌面確認。']:['Pair and refresh to check native editor availability.','配對後重新讀取原生編輯器可用狀態。']));}
$('editor-open').addEventListener('click',async()=>{if(!editorAvailable||busy||editorPending)return;editorPending=true;busy=true;const own=++generation;editorOutcome=null;render();$('editor-cancel').focus?.();try{const result=await chrome.runtime.sendMessage({type:'workflow-editor-open',language:prefs.language});if(own!==generation)return;editorOutcome=result?.schemaVersion===1&&result.outcome==='opened'?['The selected editor opened.','已開啟所選編輯器。']:result?.schemaVersion===1&&result.outcome==='cancelled'?['The desktop selection was cancelled.','已取消桌面揀選。']:['The editor request did not complete. Refresh and try again.','編輯器要求未完成，請重新讀取再試。'];}catch{if(own===generation)editorOutcome=['The editor request did not complete.','編輯器要求未完成。'];}finally{if(own===generation){editorPending=false;busy=false;render();$(editorAvailable?'editor-open':'refresh').focus?.();}}});
