function renderSchoolMode(){
 const paired=connection===true;
 if(!paired&&!schoolPending&&(school.state!=='idle'||schoolOutcome)){school={state:'idle',enabled:false,name:''};schoolOutcome=null;}
 const known=school.state==='ok';
 label($('school-heading'),['School mode','學校模式']);
 label($('school-help'),['Reads the paired desktop’s school mode name and whether it is on. Turning it on or off asks you to re-enter your vault password in the desktop (Windows Hello is not used). The password is never typed or shown in the browser.','讀取已配對桌面嘅學校模式名稱同狀態。開啟或關閉會要求你喺桌面重新輸入保險庫密碼（唔使用 Windows Hello）。密碼唔會喺瀏覽器輸入或顯示。']);
 label($('school-read'),['Read school mode','讀取學校模式']);
 label($('school-toggle'),known&&school.enabled?['Turn off school mode','關閉學校模式']:['Turn on school mode','開啟學校模式']);
 $('school-read').disabled=!paired||busy||schoolPending||school.state==='loading';
 $('school-toggle').disabled=!paired||!known||busy||schoolPending;
 let line;
 if(schoolPending)line=['Waiting for you on the desktop.','等待你喺桌面操作。'];
 else if(!paired)line=schoolOutcomes.pair;
 else if(school.state==='loading')line=['Asking the desktop…','問緊桌面…'];
 else if(school.state==='error')line=['School mode could not be read. Open and unlock the desktop, pair again and refresh.','讀取唔到學校模式。請開啟並解鎖桌面，重新配對後再重新整理。'];
 else if(schoolOutcome)line=schoolOutcome;
 else if(known)line=['Mode name: '+school.name+'. State: '+(school.enabled?'on':'off')+'.','模式名稱：'+school.name+'。狀態：'+(school.enabled?'已開啟':'已關閉')+'。'];
 else line=['School mode has not been read in this session.','今次使用期間未讀取過學校模式。'];
 label($('school-state'),line);
}
const exactKeys=(row,keys)=>row&&typeof row==='object'&&Object.keys(row).sort().join(',')===keys.slice().sort().join(',');
$('school-read').addEventListener('click',async()=>{
 if(connection!==true||busy||schoolPending||school.state==='loading')return;
 busy=true;const own=++generation;school={...school,state:'loading'};schoolOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'school-mode-read'});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1)school={state:'idle',enabled:false,name:''},schoolOutcome=schoolOutcomes.pair;
  else if(exactKeys(result,['schemaVersion','enabled','name'])&&result.schemaVersion===1&&typeof result.enabled==='boolean'&&typeof result.name==='string'&&result.name&&result.name.length<=80&&!/\p{Cc}/u.test(result.name))school={state:'ok',enabled:result.enabled,name:result.name};
  else school={state:'error',enabled:false,name:''};
 }catch{if(own===generation)school={state:'error',enabled:false,name:''};}
 finally{if(own===generation){busy=false;render();$('school-read').focus?.();}}
});
$('school-toggle').addEventListener('click',async()=>{
 if(connection!==true||busy||schoolPending||school.state!=='ok')return;
 const wanted=!school.enabled;schoolPending=true;busy=true;const own=++generation;schoolOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'school-mode-set',enabled:wanted});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1)schoolOutcome=schoolOutcomes.pair;
  else if(exactKeys(result,['schemaVersion','state','enabled'])&&result.schemaVersion===1&&['changed','unchanged','rejected','busy','unavailable'].includes(result.state)&&(result.enabled===null||typeof result.enabled==='boolean')){
   if(typeof result.enabled==='boolean')school={...school,enabled:result.enabled};
   schoolOutcome=result.state==='changed'||result.state==='unchanged'?schoolOutcomes[result.state+'-'+(school.enabled?'on':'off')]:schoolOutcomes[result.state];
  }else schoolOutcome=schoolOutcomes.failed;
 }catch{if(own===generation)schoolOutcome=schoolOutcomes.failed;}
 finally{if(own===generation){schoolPending=false;busy=false;render();$('school-toggle').focus?.();}}
});

function plainName(pair){return prefs.language==='bilingual'?pair[0]+' · '+pair[1]:t(pair);}
function isTabLocked(tab){return locks.known&&locks.locked.includes(tab);}
function lockResultText(state,tab,locked){
 const n=copy[tab];
 if(state==='changed')return locked?['The '+n[0]+' tab is now locked by the desktop.',n[1]+'分頁已由桌面鎖定。']:['The '+n[0]+' tab is now unlocked.',n[1]+'分頁已解鎖。'];
 if(state==='unchanged')return locked?['The '+n[0]+' tab was already locked. Nothing changed.',n[1]+'分頁本身已鎖定，冇改動。']:['The '+n[0]+' tab was already unlocked. Nothing changed.',n[1]+'分頁本身未鎖定，冇改動。'];
 if(state==='rejected')return ['The desktop did not confirm the change, or this lock can only be changed on the desktop. Nothing was changed.','桌面冇確認呢個更改，或者呢個鎖只可以喺桌面更改。冇任何改動。'];
 return schoolOutcomes[state]||schoolOutcomes.failed;
}
function renderLocks(){
 const paired=connection===true,stale=locks.known&&(!paired||locks.stale),active=prefs.tab;
 $('locks-section').hidden=active!=='status';
 label($('locks-heading'),['Locks','鎖']);
 label($('locks-help'),['Reads which workspace tabs the paired desktop has locked. Locking or unlocking a tab asks you to re-enter your vault password in the desktop (Windows Hello is not used); nothing is typed or shown here. This page never unlocks anything by itself. The Status tab holds these controls, so it cannot be locked from the browser.','讀取已配對桌面鎖咗邊啲工作區分頁。鎖定或解鎖分頁會要求你喺桌面重新輸入保險庫密碼（唔使用 Windows Hello），呢度唔會輸入或顯示任何嘢。呢頁永遠唔會自己解鎖。狀態分頁載有呢啲控制項，所以唔可以喺瀏覽器鎖定。']);
 label($('locks-read'),['Read locks','讀取鎖定']);
 $('locks-read').disabled=!paired||busy||lockPending!==null||locks.loading;
 let line;
 if(lockPending)line=['Waiting for you on the desktop.','等待你喺桌面操作。'];
 else if(locks.loading)line=['Asking the desktop…','問緊桌面…'];
 else if(lockOutcome)line=lockOutcome;
 else if(locks.failed)line=['Locks could not be read. Open and unlock the desktop, pair again and refresh.','讀取唔到鎖定狀態。請開啟並解鎖桌面，重新配對後再重新整理。'];
 else if(!locks.known&&!paired)line=schoolOutcomes.pair;
 else if(locks.known)line=locks.locked.length?['Locked tabs: '+locks.locked.length+' of '+LOCK_TABS.length+'.','已鎖定分頁：'+locks.locked.length+' / '+LOCK_TABS.length+'。']:['No tab is locked.','冇分頁被鎖定。'];
 else line=['Locks have not been read in this session.','今次使用期間未讀取過鎖定狀態。'];
 label($('locks-state'),line);
 $('locks-stale').hidden=!stale;
 if(stale)label($('locks-stale'),['This list comes from an earlier read and may be out of date because the desktop cannot be reached now. Pair the browser and read again.','呢份清單來自較早嘅讀取，而家聯絡唔到桌面，所以可能已經過時。請配對瀏覽器再讀取。']);
 const ready=paired&&locks.known&&!busy&&lockPending===null&&!locks.loading;
 for(const tab of LOCK_TABS){
  const locked=isTabLocked(tab),name=copy[tab];
  label($('lock-'+tab+'-name'),name);
  label($('lock-'+tab+'-state'),!locks.known?['Not read','未讀取']:locked?['Locked','已鎖定']:['Unlocked','未鎖定']);
  label($('lock-'+tab+'-lock'),['Lock','鎖定']);
  label($('lock-'+tab+'-unlock'),['Unlock','解鎖']);
  $('lock-'+tab+'-lock').setAttribute('aria-label',plainName(['Lock the '+name[0]+' tab','鎖定'+name[1]+'分頁']));
  $('lock-'+tab+'-unlock').setAttribute('aria-label',plainName(['Unlock the '+name[0]+' tab','解鎖'+name[1]+'分頁']));
  $('lock-'+tab+'-lock').disabled=!ready||locked||tab==='status';
  $('lock-'+tab+'-unlock').disabled=!ready||!locked;
 }
 // A locked section keeps its card on Home but is marked disabled, and choosing it shows an explanation instead of its panel.
 for(const item of document.querySelectorAll('[data-tab]')){
  const tab=item.dataset.tab,locked=isTabLocked(tab),mark=$('lock-mark-'+tab);
  item.setAttribute('aria-disabled',String(locked));
  mark.hidden=!locked;mark.textContent=locked?'🔒':'';
  if(locked){
   item.removeAttribute('aria-labelledby');
   item.setAttribute('aria-label',plainName([copy[tab][0]+', locked by the desktop',copy[tab][1]+'，已由桌面鎖定']));
   label($('desc-'+tab),['Locked by the desktop. Open it to see why.','已由桌面鎖定。開啟查看原因。']);
  }else{item.removeAttribute('aria-label');item.setAttribute('aria-labelledby','title-'+tab);}
 }
 const showNote=isTabLocked(active);
 $('locked-note').hidden=!showNote;
 if(showNote){
  $('panel-'+active).hidden=true;
  label($('locked-heading'),[copy[active][0]+' is locked',copy[active][1]+'已鎖定']);
  label($('locked-text'),active==='status'?['The desktop has locked this tab. The Locks section stays available so you can ask the desktop to unlock it; you will be asked for your vault password there.','桌面已鎖定呢個分頁。「鎖」部分保持可用，你可以要求桌面解鎖，到時要喺桌面輸入保險庫密碼。']:['The desktop has locked this tab. Open the Status tab, find Locks and ask the desktop to unlock it; you will be asked for your vault password there.','桌面已鎖定呢個分頁。請開啟狀態分頁，喺「鎖」部分要求桌面解鎖，到時要喺桌面輸入保險庫密碼。']);
 }
}
$('locks-read').addEventListener('click',async()=>{
 if(connection!==true||busy||lockPending!==null||locks.loading)return;
 busy=true;const own=++generation;locks={...locks,loading:true,failed:false};lockOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'element-locks-read'});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1){locks={...locks,loading:false,stale:true};lockOutcome=schoolOutcomes.pair;}
  else if(exactKeys(result,['schemaVersion','locked'])&&result.schemaVersion===1&&Array.isArray(result.locked)&&result.locked.length<=LOCK_TABS.length&&result.locked.every(tab=>LOCK_TABS.includes(tab))&&new Set(result.locked).size===result.locked.length)locks={known:true,locked:LOCK_TABS.filter(tab=>result.locked.includes(tab)),stale:false,loading:false,failed:false};
  else locks={...locks,loading:false,stale:true,failed:!locks.known};
 }catch{if(own===generation)locks={...locks,loading:false,stale:true,failed:!locks.known};}
 finally{if(own===generation){busy=false;render();$('locks-read').focus?.();}}
});
async function changeLock(tab,wanted){
 if(connection!==true||busy||lockPending!==null||locks.loading||!locks.known||wanted&&tab==='status')return;
 lockPending={tab,wanted};busy=true;const own=++generation;lockOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'element-lock-set',target:tab,locked:wanted});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1){lockOutcome=schoolOutcomes.pair;locks={...locks,stale:true};}
  else if(exactKeys(result,['schemaVersion','state','target','locked'])&&result.schemaVersion===1&&result.target===tab&&['changed','unchanged','rejected','busy','unavailable'].includes(result.state)&&(result.locked===null||typeof result.locked==='boolean')&&(result.locked!==null||!['changed','unchanged'].includes(result.state))){
   if(typeof result.locked==='boolean')locks={...locks,locked:LOCK_TABS.filter(name=>name===tab?result.locked:locks.locked.includes(name))};
   else locks={...locks,stale:true};
   lockOutcome=lockResultText(result.state,tab,result.locked);
  }else{lockOutcome=schoolOutcomes.failed;locks={...locks,stale:true};}
 }catch{if(own===generation){lockOutcome=schoolOutcomes.failed;locks={...locks,stale:true};}}
 finally{if(own===generation){lockPending=null;busy=false;render();$('locks-read').focus?.();}}
}
for(const tab of LOCK_TABS){
 $('lock-'+tab+'-lock').addEventListener('click',()=>changeLock(tab,true));
 $('lock-'+tab+'-unlock').addEventListener('click',()=>changeLock(tab,false));
}

// Unlock level (Status tab). The desktop owns the ladder, its cooldown and its credential check; this page only reads and asks.
// Nothing is sent until the person chooses a button, and the last read stays in memory for this page session only.
function ladderIndex(){return ladder.known?ladder.levels.indexOf(ladder.level):-1;}
function ladderRemaining(){return ladder.cooldownUntil===null?0:Math.max(0,Math.ceil((ladder.cooldownUntil-Date.now())/1000));}
function waitText(seconds){return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function stopLadderTimer(){if(ladderTimer!==null){clearTimeout(ladderTimer);ladderTimer=null;}}
function tickLadder(){ladderTimer=null;if(ladder.cooldownUntil!==null&&ladderRemaining()===0)ladder={...ladder,cooldownUntil:null};renderLadder();}
function renderLadder(){
 const paired=connection===true,stale=ladder.known&&(!paired||ladder.stale),index=ladderIndex(),top=ladder.levels.length-1,remaining=ladderRemaining();
 $('ladder-section').hidden=prefs.tab!=='status';
 label($('ladder-heading'),['Unlock level','解鎖級別']);
 label($('ladder-help'),['Reads where the desktop sits on its unlock ladder. Requesting the next step asks you to re-enter your vault password in the desktop (Windows Hello is not used); the desktop runs its own checks and its own cooldown, and nothing is typed or shown here. A running cooldown is never skipped.','讀取桌面喺解鎖階梯嘅位置。要求下一步會請你喺桌面重新輸入保險庫密碼（唔使用 Windows Hello）；檢查同冷卻都由桌面自己處理，呢度唔會輸入或顯示任何嘢。進行中嘅冷卻永遠唔會被跳過。']);
 label($('ladder-read'),['Read level','讀取級別']);
 label($('ladder-step'),['Request next step','要求下一步']);
 $('ladder-read').disabled=!paired||busy||ladderPending||ladder.loading;
 $('ladder-step').disabled=!paired||!ladder.known||busy||ladderPending||ladder.loading||index<=0||remaining>0;
 $('ladder-progress').hidden=!ladder.known;
 if(ladder.known){
  $('ladder-progress').max=1;$('ladder-progress').value=top>0&&index>=0?index/top:0;
  $('ladder-progress').setAttribute('aria-label',plainName(['Unlock level '+index+' of '+top,'解鎖級別 '+index+' / '+top]));
 }
 let line;
 if(ladderPending)line=['Waiting for you on the desktop.','等待你喺桌面操作。'];
 else if(ladder.loading)line=['Asking the desktop…','問緊桌面…'];
 else if(ladderOutcome)line=ladderOutcome;
 else if(ladder.failed)line=['The unlock level could not be read. Open and unlock the desktop, pair again and refresh.','讀取唔到解鎖級別。請開啟並解鎖桌面，重新配對後再重新整理。'];
 else if(!ladder.known&&!paired)line=schoolOutcomes.pair;
 else if(ladder.known)line=['Unlock level '+index+' of '+top+'.','解鎖級別 '+index+' / '+top+'。'];
 else line=['The unlock level has not been read in this session.','今次使用期間未讀取過解鎖級別。'];
 label($('ladder-state'),line);
 $('ladder-cooldown').hidden=!(ladder.known&&remaining>0);
 if(ladder.known&&remaining>0)label($('ladder-cooldown'),['Cooling down: '+waitText(remaining)+' left.','冷卻中：仲有 '+waitText(remaining)+'。']);
 $('ladder-recovery').hidden=!ladder.known;
 if(ladder.known)label($('ladder-recovery'),ladder.recovery==='required'?['Recovery is required. Use the desktop.','需要復原。請使用桌面。']:ladder.recovery==='available'?['Recovery is available on the desktop.','桌面提供復原。']:['No recovery is needed.','唔需要復原。']);
 $('ladder-stale').hidden=!stale;
 if(stale)label($('ladder-stale'),['This reading comes from an earlier read and may be out of date because the desktop cannot be reached now. Pair the browser and read again.','呢個讀數來自較早嘅讀取，而家聯絡唔到桌面，所以可能已經過時。請配對瀏覽器再讀取。']);
 // One timer at a time, and only while a countdown is visible. It does not keep a test runner or a closing page alive.
 if(ladder.known&&remaining>0&&prefs.tab==='status'){if(ladderTimer===null){ladderTimer=setTimeout(tickLadder,1000);ladderTimer?.unref?.();}}else stopLadderTimer();
}
$('ladder-read').addEventListener('click',async()=>{
 if(connection!==true||busy||ladderPending||ladder.loading)return;
 busy=true;const own=++generation;ladder={...ladder,loading:true,failed:false};ladderOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'unlock-ladder-read'});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1){ladder={...ladder,loading:false,stale:true};ladderOutcome=ladderOutcomes.pair;}
  else if(exactKeys(result,['schemaVersion','level','levels','cooldownUntil','recovery'])&&result.schemaVersion===1&&ladderLevelsOk(result.levels)&&result.levels.includes(result.level)&&ladderTimeOk(result.cooldownUntil)&&['none','available','required'].includes(result.recovery))ladder={known:true,level:result.level,levels:result.levels.slice(),cooldownUntil:result.cooldownUntil,recovery:result.recovery,stale:false,loading:false,failed:false};
  else ladder={...ladder,loading:false,stale:true,failed:!ladder.known};
 }catch{if(own===generation)ladder={...ladder,loading:false,stale:true,failed:!ladder.known};}
 finally{if(own===generation){busy=false;render();$('ladder-read').focus?.();}}
});
$('ladder-step').addEventListener('click',async()=>{
 if(connection!==true||busy||ladderPending||ladder.loading||!ladder.known||ladderIndex()<=0||ladderRemaining()>0)return;
 ladderPending=true;busy=true;const own=++generation;ladderOutcome=null;render();
 try{
  const result=await chrome.runtime.sendMessage({type:'unlock-step-request'});if(own!==generation)return;
  if(result?.paired===false&&Object.keys(result).length===1){ladderOutcome=ladderOutcomes.pair;ladder={...ladder,stale:true};}
  else if(exactKeys(result,['schemaVersion','state','level','cooldownUntil'])&&result.schemaVersion===1&&LADDER_STATES.includes(result.state)&&(result.level===null||typeof result.level==='string'&&ladder.levels.includes(result.level))&&ladderTimeOk(result.cooldownUntil)){
   ladder=result.level===null?{...ladder,stale:true}:{...ladder,level:result.level,cooldownUntil:result.cooldownUntil,stale:false};
   ladderOutcome=ladderOutcomes[result.state];
  }else{ladderOutcome=ladderOutcomes.failed;ladder={...ladder,stale:true};}
 }catch{if(own===generation){ladderOutcome=ladderOutcomes.failed;ladder={...ladder,stale:true};}}
 finally{if(own===generation){ladderPending=false;busy=false;render();$('ladder-read').focus?.();}}
});

const VERSION_PATTERN=/^\d{1,9}\.\d{1,9}\.\d{1,9}(?:-[0-9A-Za-z.-]{1,32})?$/;
function readDesktop(result){
 if(result?.paired===false&&Object.keys(result).length===1)return {state:'unpaired'};
 const update=result?.update,exact=(row,keys)=>row&&typeof row==='object'&&Object.keys(row).sort().join(',')===keys.sort().join(',');
 if(!exact(result,['schemaVersion','lock','update'])||result.schemaVersion!==1||!Object.hasOwn(desktopLockCopy,result.lock)||!exact(update,['desktopVersion','availableVersion','phase','progress'])||!Object.hasOwn(desktopPhaseCopy,update.phase)||update.desktopVersion!=='unknown'&&!VERSION_PATTERN.test(update.desktopVersion)||update.availableVersion!==null&&!VERSION_PATTERN.test(update.availableVersion)||update.progress!==null&&!(Number.isFinite(update.progress)&&update.progress>=0&&update.progress<=1))return {state:'error'};
 return {state:'ok',lock:result.lock,update:{desktopVersion:update.desktopVersion,availableVersion:update.availableVersion,phase:update.phase,progress:update.progress}};
}
function renderDesktop(){
 const ok=desktop.state==='ok',update=ok?desktop.update:null,running=update?.desktopVersion,packaged=provenance?.desktopVersion;
 label($('desktop-state'),desktop.state==='loading'?['Asking the desktop…','問緊桌面…']:desktop.state==='unpaired'?['Pair the browser first, on the Connection tab.','請先喺「連線」分頁配對瀏覽器。']:desktop.state==='error'?['The desktop did not answer. Open and unlock it, pair again and refresh.','桌面冇回應。請開啟並解鎖桌面，重新配對後再重新整理。']:ok?['Desktop status refreshed.','桌面狀態已重新整理。']:['Desktop status has not been read in this session.','今次使用期間未讀取過桌面狀態。']);
 label($('desktop-lock'),ok?desktopLockCopy[desktop.lock]:['Desktop lock state: not read','桌面鎖定狀態：未讀取']);
 label($('desktop-version'),ok?(running==='unknown'?['Desktop version: unavailable','桌面版本：未可用']:['Desktop version: '+running,'桌面版本：'+running]):['Desktop version: not read','桌面版本：未讀取']);
 label($('desktop-update'),ok?(update.availableVersion?[desktopPhaseCopy[update.phase][0]+' (version '+update.availableVersion+')',desktopPhaseCopy[update.phase][1]+'（版本 '+update.availableVersion+'）']:desktopPhaseCopy[update.phase]):['Update: not read','更新：未讀取']);
 const bar=$('desktop-progress'),reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches===true;
 bar.hidden=!(ok&&['downloading','ready'].includes(update.phase));
 if(!bar.hidden){bar.indeterminate=update.progress===null&&!reduced;bar.value=update.progress??0;}
 label($('desktop-compat'),!ok?['Extension and desktop versions are compared after a refresh.','重新整理後會比較擴充功能同桌面嘅版本。']:running==='unknown'||typeof packaged!=='string'||!VERSION_PATTERN.test(packaged)?['The version this extension was packaged with is unknown, so it cannot be compared with the desktop.','唔知道呢個擴充功能打包時用邊個版本，所以無法同桌面比較。']:packaged===running?['The extension and the desktop are the same version ('+running+').','擴充功能同桌面係同一版本（'+running+'）。']:['This extension was packaged with desktop '+packaged+' but the desktop is now '+running+'. Load the extension again from the folder app-'+running+'\\resources\\browser-extension on the browser extensions page.','呢個擴充功能係用桌面 '+packaged+' 打包，但桌面而家係 '+running+'。請喺瀏覽器擴充功能頁面，重新由 app-'+running+'\\resources\\browser-extension 資料夾載入。']);
 $('desktop-refresh').disabled=desktop.state==='loading';
}
$('desktop-refresh').addEventListener('click',async()=>{
 if(desktop.state==='loading')return;
 desktop={state:'loading'};renderDesktop();
 try{desktop=readDesktop(await chrome.runtime.sendMessage({type:'desktop-status'}));}catch{desktop={state:'error'};}
 renderDesktop();
});
var converterView=mountBrowserConverter($('browser-converter'),{send:message=>chrome.runtime.sendMessage(message),getLanguage:()=>prefs.language,acquire:()=>{if(busy||editorPending)return false;converterBusy=true;busy=true;render();return true;},release:()=>{if(!converterBusy)return;converterBusy=false;busy=editorPending;render();},isExternallyBusy:()=>editorPending||busy&&!converterBusy,disconnect:()=>{generation++;busy=false;editorAvailable=false;connection=false;protection=null;void chrome.runtime.sendMessage({type:'disconnect'}).catch(()=>{});render();$('refresh').focus?.();}});
